create or replace function public.ss_agent_execution_reserve(p_id uuid,p_owner uuid,p_micro_cny bigint,p_month text,p_run text,p_month_cap bigint,p_run_cap bigint,p_expires_at timestamptz)
returns boolean language plpgsql security invoker set search_path='' as $$
declare month_budget public.ss_agent_execution_budgets; run_budget public.ss_agent_execution_budgets;
begin
  if p_micro_cny<=0 or p_micro_cny>10000000 or p_month_cap<=0 or p_month_cap>100000000 or p_run_cap<=0 or p_run_cap>100000000
    or p_month<>pg_catalog.to_char(now() at time zone 'Asia/Shanghai','YYYY-MM') or p_run !~ '^[A-Za-z0-9_-]{1,64}$'
    or p_expires_at<=now() or p_expires_at>now()+interval '30 minutes' then raise exception 'invalid_budget_reservation'; end if;
  -- Single global capacity lock also covers month rollover and different Node instances.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('ss_agent_execution_capacity',0));
  if exists(select 1 from public.ss_agent_execution_reservations where id=p_id) then
    return exists(select 1 from public.ss_agent_execution_reservations where id=p_id and owner_uuid=p_owner and reserved_micro_cny=p_micro_cny);
  end if;
  if exists(select 1 from public.ss_agent_execution_reservations where released_at is null and expires_at>now()) then return false; end if;
  if (select count(*) from public.ss_agent_execution_reservations where owner_uuid=p_owner and created_at>now()-interval '24 hours')>=10 then return false; end if;
  insert into public.ss_agent_execution_budgets(period_key,cap_micro_cny)
  values('month:'||p_month,p_month_cap),('run:'||p_run,p_run_cap)
  on conflict(period_key) do update set cap_micro_cny=least(public.ss_agent_execution_budgets.cap_micro_cny,excluded.cap_micro_cny);
  select * into month_budget from public.ss_agent_execution_budgets where period_key='month:'||p_month for update;
  select * into run_budget from public.ss_agent_execution_budgets where period_key='run:'||p_run for update;
  if month_budget.reserved_micro_cny+p_micro_cny>month_budget.cap_micro_cny or run_budget.reserved_micro_cny+p_micro_cny>run_budget.cap_micro_cny then return false; end if;
  update public.ss_agent_execution_budgets set reserved_micro_cny=reserved_micro_cny+p_micro_cny where period_key in ('month:'||p_month,'run:'||p_run);
  insert into public.ss_agent_execution_reservations(id,owner_uuid,month_key,run_key,reserved_micro_cny,expires_at)
  values(p_id,p_owner,p_month,p_run,p_micro_cny,p_expires_at);
  return true;
end $$;
