-- 【ss_ StudySolo】User feedback on completed AI answers. Apply after coordinator review.
begin;

create table if not exists public.ss_chat_feedback (
  id uuid primary key default gen_random_uuid(),
  user_uuid uuid not null references auth.users(id) on delete cascade,
  session_id text not null check (session_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'),
  message_id text not null check (message_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'),
  feedback_slot text not null check (feedback_slot in ('vote','report')),
  feedback_type text not null check (feedback_type in ('like','dislike','report')),
  report_reason text,
  feedback_text text check (feedback_text is null or (char_length(feedback_text) between 1 and 1000 and octet_length(feedback_text) <= 4000)),
  answer_excerpt text check (answer_excerpt is null or (char_length(answer_excerpt) <= 600 and octet_length(answer_excerpt) <= 2400)),
  status text not null default 'open' check (status in ('open','in_progress','resolved','dismissed')),
  revision integer not null default 1 check (revision > 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  processed_at timestamptz,
  processed_by uuid references auth.users(id) on delete set null,
  constraint ss_chat_feedback_slot_type check (
    (feedback_slot = 'vote' and feedback_type in ('like','dislike') and report_reason is null)
    or (feedback_slot = 'report' and feedback_type = 'report' and report_reason in ('inaccurate','unsafe','privacy','other')
      and feedback_text is not null and char_length(btrim(feedback_text)) between 3 and 1000)
  ),
  constraint ss_chat_feedback_processed_state check (
    (status in ('resolved','dismissed')) = (processed_at is not null)
    and (processed_by is null or processed_at is not null)
  ),
  constraint ss_chat_feedback_owner_message_slot unique (user_uuid,session_id,message_id,feedback_slot)
);

create index if not exists ss_chat_feedback_queue on public.ss_chat_feedback(status,created_at desc,id desc);
create index if not exists ss_chat_feedback_type_queue on public.ss_chat_feedback(feedback_type,status,created_at desc,id desc);
create index if not exists ss_chat_feedback_owner_history on public.ss_chat_feedback(user_uuid,session_id,message_id);

alter table public.ss_chat_feedback enable row level security;
revoke all on public.ss_chat_feedback from public,anon,authenticated;
grant select,insert,update on public.ss_chat_feedback to service_role;

create or replace function public.ss_chat_feedback_vote(
  p_user_uuid uuid,
  p_session_id text,
  p_message_id text,
  p_vote text
) returns jsonb
language plpgsql security invoker set search_path = '' as $$
declare item public.ss_chat_feedback;
begin
  if p_user_uuid is null or p_vote is null or p_vote not in ('like','dislike')
    or p_session_id is null or p_message_id is null
    or p_session_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
    or p_message_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$' then
    raise exception 'invalid_chat_feedback';
  end if;

  insert into public.ss_chat_feedback(user_uuid,session_id,message_id,feedback_slot,feedback_type)
    values(p_user_uuid,p_session_id,p_message_id,'vote',p_vote)
  on conflict(user_uuid,session_id,message_id,feedback_slot) do update set
    feedback_type=excluded.feedback_type,
    feedback_text=null,
    answer_excerpt=null,
    status='open',
    revision=public.ss_chat_feedback.revision+1,
    updated_at=pg_catalog.now(),
    processed_at=null,
    processed_by=null
  where public.ss_chat_feedback.feedback_type is distinct from excluded.feedback_type
  returning * into item;

  if not found then
    select * into strict item from public.ss_chat_feedback
      where user_uuid=p_user_uuid and session_id=p_session_id and message_id=p_message_id and feedback_slot='vote';
  end if;

  return pg_catalog.jsonb_build_object(
    'id',item.id,'feedback_type',item.feedback_type,'revision',item.revision,'status',item.status,
    'report_reason',item.report_reason,'feedback_text',item.feedback_text,'answer_excerpt',item.answer_excerpt
  );
end
$$;

create or replace function public.ss_chat_feedback_report(
  p_user_uuid uuid,
  p_session_id text,
  p_message_id text,
  p_reason text,
  p_feedback_text text,
  p_answer_excerpt text default null
) returns jsonb
language plpgsql security invoker set search_path = '' as $$
declare item public.ss_chat_feedback;
begin
  if p_user_uuid is null or p_reason is null or p_reason not in ('inaccurate','unsafe','privacy','other')
    or p_session_id is null or p_message_id is null
    or p_session_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
    or p_message_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
    or p_feedback_text is null or pg_catalog.char_length(pg_catalog.btrim(p_feedback_text)) not between 3 and 1000
    or pg_catalog.octet_length(p_feedback_text)>4000
    or (p_answer_excerpt is not null and (pg_catalog.char_length(p_answer_excerpt)>600 or pg_catalog.octet_length(p_answer_excerpt)>2400)) then
    raise exception 'invalid_chat_feedback';
  end if;

  insert into public.ss_chat_feedback(user_uuid,session_id,message_id,feedback_slot,feedback_type,report_reason,feedback_text,answer_excerpt)
    values(p_user_uuid,p_session_id,p_message_id,'report','report',p_reason,p_feedback_text,p_answer_excerpt)
  on conflict(user_uuid,session_id,message_id,feedback_slot) do update set
    report_reason=excluded.report_reason,
    feedback_text=excluded.feedback_text,
    answer_excerpt=excluded.answer_excerpt,
    status='open',
    revision=public.ss_chat_feedback.revision+1,
    updated_at=pg_catalog.now(),
    processed_at=null,
    processed_by=null
  where public.ss_chat_feedback.feedback_type is distinct from excluded.feedback_type
    or public.ss_chat_feedback.report_reason is distinct from excluded.report_reason
    or public.ss_chat_feedback.feedback_text is distinct from excluded.feedback_text
    or public.ss_chat_feedback.answer_excerpt is distinct from excluded.answer_excerpt
  returning * into item;

  if not found then
    select * into strict item from public.ss_chat_feedback
      where user_uuid=p_user_uuid and session_id=p_session_id and message_id=p_message_id and feedback_slot='report';
  end if;

  return pg_catalog.jsonb_build_object(
    'id',item.id,'feedback_type',item.feedback_type,'revision',item.revision,'status',item.status,
    'report_reason',item.report_reason,'feedback_text',item.feedback_text,'answer_excerpt',item.answer_excerpt
  );
end
$$;

revoke all on function public.ss_chat_feedback_vote(uuid,text,text,text) from public,anon,authenticated,service_role;
revoke all on function public.ss_chat_feedback_report(uuid,text,text,text,text,text) from public,anon,authenticated,service_role;
grant execute on function public.ss_chat_feedback_vote(uuid,text,text,text) to service_role;
grant execute on function public.ss_chat_feedback_report(uuid,text,text,text,text,text) to service_role;

comment on table public.ss_chat_feedback is '【ss_ StudySolo】Account-owned AI answer votes and reports. Service-only access; stores message location and at most a user-opted-in short redacted answer excerpt, never chat history.';
comment on column public.ss_chat_feedback.user_uuid is 'Canonical Account UUID from live Account introspection; never accepted from browser request JSON.';
comment on column public.ss_chat_feedback.feedback_slot is 'One vote slot and one report slot per user/session/message; votes switch in place without duplicate rows.';
comment on column public.ss_chat_feedback.feedback_text is 'Bounded free-text vote details or required report explanation; maximum 1000 characters, common contacts/credentials redacted by the server.';
comment on column public.ss_chat_feedback.answer_excerpt is 'Optional, explicitly user-selected, server-redacted answer excerpt; maximum 600 characters.';

commit;

-- Tighten the report-slot invariant: SQL CHECK accepts UNKNOWN, so the
-- enum membership check in 003 alone does not reject a NULL report_reason.
begin;

alter table public.ss_chat_feedback
  add constraint ss_chat_feedback_report_reason_not_null
  check (feedback_slot <> 'report' or report_reason is not null);

comment on constraint ss_chat_feedback_report_reason_not_null on public.ss_chat_feedback is
  '【ss_ StudySolo】Every report row must carry a non-null reason; vote rows may omit one.';

commit;

-- 【ss_ StudySolo】Override Supabase default grants on these service-only tables.
-- Revoke unused TRUNCATE/REFERENCES/TRIGGER and content deletion privileges.
begin;

revoke all on public.ss_connector_records, public.ss_connector_leases,
  public.ss_agent_execution_records, public.ss_agent_execution_locks,
  public.ss_agent_execution_budgets, public.ss_agent_execution_reservations,
  public.ss_chat_feedback from public, anon, authenticated, service_role;

grant select, insert, update on public.ss_connector_records,
  public.ss_agent_execution_records, public.ss_agent_execution_budgets,
  public.ss_agent_execution_reservations, public.ss_chat_feedback to service_role;

-- Security-invoker unlock functions delete only ephemeral coordination leases.
grant select, insert, update, delete on public.ss_connector_leases,
  public.ss_agent_execution_locks to service_role;

commit;
